import { randomUUID } from 'node:crypto'
import fs from 'fs'
import path from 'path'

// The install id identifies one *installation*, not one customer, and that is
// exactly why it lives in userData rather than being baked into the package:
//
//  - userData survives an in-place update (NSIS overwrites the install dir,
//    the AppImage is replaced wholesale), so the same shop keeps reporting the
//    same id release after release and does not look like a new install every
//    time it updates. A packaged-in id would be regenerated by whoever builds
//    the release, which would make the count meaningless.
//  - A clean reinstall on a different machine produces a NEW id, and that is
//    the signal we actually want: the update proxy sees how many distinct
//    installations sit behind one product key, which is how a copied .exe
//    passed around between shops becomes visible.
//
// Deliberately not a security control: the file is plain text a user can
// delete or copy. It buys visibility, not enforcement (revocation happens at
// the key level, server side).
// Both filesystem accesses are best-effort on purpose. This value is called
// from the whenReady handler in main.ts, at the point where the window has
// already been created, and it feeds a purely optional feature. An escaping
// throw there rejects the async whenReady callback with nothing to catch it,
// which under Node's default unhandled-rejection mode takes the whole main
// process down: a shop whose userData partition filled up, or whose
// install-id file ended up read-only or owned by another user, would get a
// window that opens and then dies. Losing the ability to persist the id costs
// nothing but an inflated installation count on the proxy side, so degrade to
// an id that lives only for this session rather than crash. Deliberately not
// logged here: this module stays dependency-free (no electron-log) so it is
// trivially testable outside Electron, and the proxy already sees the churn.
export function resolveInstallId(userDataPath: string): string {
  const idPath = path.join(userDataPath, 'install-id')
  try {
    // Trim on read (resolveJwtSecret does not, because its value only ever
    // becomes an env var): this string is sent as an HTTP header value, and
    // Electron's net module throws on a header containing CR/LF. A file
    // hand-edited or written by a text editor that appends a trailing
    // newline would otherwise break every update check silently.
    const stored = fs.readFileSync(idPath, 'utf-8').trim()
    // A zero-byte file is exactly what a previous write that ran out of disk
    // leaves behind, and '' is not a usable header value. Regenerating beats
    // pinning the installation to a blank id for the rest of its life.
    if (stored) return stored
  } catch {
    // Covers both "file does not exist" (the normal first-run path, which is
    // why there is no existsSync check anymore: the stat would be a second
    // syscall racing the read for no benefit) and an unreadable file.
  }
  const id = randomUUID()
  try {
    fs.writeFileSync(idPath, id, 'utf-8')
  } catch {
    // Ephemeral id for this session, see the note above the function.
  }
  return id
}
